input.command:
cd /tmp && probe() { desc="$1"; shift; rm -f /tmp/o /tmp/e; timeout 12 /workspace/dataset/test20_executable "$@" > /tmp/o 2> /tmp/e; rc=$?; echo "=== $desc ==="; echo "RC=$rc  stdout_bytes=$(wc -c < /tmp/o)"; echo "-- STDOUT (first 400B) --"; head -c 400 /tmp/o | cat -A; echo "-- STDERR (first 2000B) --"; head -c 2000 /tmp/e | cat -A; }; 
probe "f = -1"  --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f -1 --g 2
probe "f = -1 (equals form)"  --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f=-1 --g 2

cd /tmp && D4300=$(printf '9%.0s' $(seq 1 4300)); D4301=$(printf '9%.0s' $(seq 1 4301)); D5000=$(printf '9%.0s' $(seq 1 5000)); 
echo "len4300=${#D4300} len4301=${#D4301} len5000=${#D5000}";
for v in "$D4300" "$D4301" "$D5000"; do rm -f /tmp/o /tmp/e; timeout 20 /workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f "$v" --g 2 > /tmp/o 2> /tmp/e; rc=$?; echo "=== f digits=${#v} RC=$rc stdout=$(wc -c < /tmp/o)B ==="; echo "STDOUT line5 len: $(sed -n 5p /tmp/o | wc -c)"; echo "-- ERR (truncated to 500B) --"; head -c 500 /tmp/e | cat -A; echo; done

cd /tmp && probe() { desc="$1"; shift; rm -f /tmp/o /tmp/e; timeout 20 /workspace/dataset/test20_executable "$@" > /tmp/o 2> /tmp/e; rc=$?; echo "=== $desc RC=$rc stdout=$(wc -c < /tmp/o)B errB=$(wc -c < /tmp/e) ==="; head -c 200 /tmp/o|cat -A; head -c 160 /tmp/e|cat -A; echo; }; 
Z5000=$(printf '0%.0s' $(seq 1 5000)); D4301=$(printf '9%.0s' $(seq 1 4301));
probe "f = 5000 zeros"          --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f "$Z5000" --g 2
probe "f = 0 then 4301 nines"   --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f "0$D4301" --g 2
probe "f = -(4301 nines)"       --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f "-$D4301" --g 2
probe "g = 4301 nines"          --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f 1 --g "$D4301"

cd /tmp && echo "### pipe to head -2"; /workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f 1 --g 2 2>/tmp/e | head -2; echo "RC_prog=${PIPESTATUS[0]}"; echo "-- ERR --"; cat -A /tmp/e;
echo; echo "### pipe to true (closes immediately)"; /workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f 1 --g 2 2>/tmp/e2 | true; echo "RC_prog=${PIPESTATUS[0]}"; cat -A /tmp/e2;
echo; echo "### stdout closed (>&-)"; /workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f 1 --g 2 >&- 2>/tmp/e3; echo "RC=$?"; cat -A /tmp/e3;
echo; echo "### stdout to /dev/full"; /workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f 1 --g 2 >/dev/full 2>/tmp/e4; echo "RC=$?"; cat -A /tmp/e4
